}

Method.Source:
/// <summary>
/// Retrieves the <c>LedgerDimensionDefaultAccount</c> value that is used for posting duty component COGS.
/// </summary>
/// <returns>
/// The <c>LedgerDimensionDefaultAccount</c> value that is used for posting duty component COGS.
/// </returns>
public LedgerDimensionDefaultAccount METLedgerDimensionLineAccountConsumption()
{
    return salesLine.accountConsumptionLedgerDimension(salesLine.inventTable());
}

protected boolean  checkBlockedLevel()
{
    int fromLine = infologLine();
    boolean  ok = next checkBlockedLevel();

    if (!ok && this.parmDocumentStatus() == DocumentStatus::Invoice && salesTable)
    {
        METVendParameters vendParameters;

        select firstonly SalesOrderType from vendParameters;

        CustVendorBlocked   blockStatus   = CustTable::find(salesTable.CustAccount).Blocked;

        // Verify if the CustAccount is blocked post sales invoice should not trigger
        if (salesTable.METSalesOrderType == vendParameters.SalesOrderType && blockStatus == CustVendorBlocked::METSalesinvoice)
        {
            ok = true;

            if (infologLine() > fromLine)
            {
                infolog.cut(fromLine + 1);
            }
        }
    }

    return ok;
}
